/** Directional variants derived from `chevron-down` (Figma has a single chevron glyph). Rotation in degrees. */
export const ICON_ALIASES = {
  'chevron-up': { base: 'chevron-down', rotate: 180 },
  'chevron-left': { base: 'chevron-down', rotate: 90 },
  'chevron-right': { base: 'chevron-down', rotate: -90 },
} as const satisfies Record<string, { base: keyof typeof ICONS; rotate: number }>;

export type IconName = keyof typeof ICONS | keyof typeof ICON_ALIASES;

/** Every icon name, glyphs first, then derived aliases. */
export const ICON_NAMES = [
  ...(Object.keys(ICONS) as (keyof typeof ICONS)[]),
  ...(Object.keys(ICON_ALIASES) as (keyof typeof ICON_ALIASES)[]),
] as IconName[];

/** Resolves a name to its definition plus the CSS rotation (degrees) to apply. */
export function resolveIcon(name: IconName): { def: IconDef; rotate: number } {
  if (name in ICON_ALIASES) {
    const alias = ICON_ALIASES[name as keyof typeof ICON_ALIASES];
    return { def: ICONS[alias.base] as IconDef, rotate: alias.rotate };
  }
  return { def: ICONS[name as keyof typeof ICONS] as IconDef, rotate: 0 };
}
